"""Human-facing case and site-pack documents generated by the CLI."""

from __future__ import annotations

from .models import TargetProfile


def scope_markdown(slug: str, target: TargetProfile) -> str:
    auth = "yes" if target.authorized else "NO — confirm authorization before any network act"
    return f"""# Scope — {slug}

> This file is the gate. No probing, browser launch, login, or bulk request should
> happen until the scope is explicit. Keep it short, concrete, and current.

## 1. Authorization

- Authorized by: {auth}
- Basis: owner / written permission / public data / internal test environment
- Restrictions imposed by the owner:

## 2. Target

- Entry URL: {target.url}
- Target kind: {target.kind}
- Authentication mode: {target.auth}
- Geography / locale: {target.geo or "not specified"}
- Expected volume: {target.volume} items or pages
- Data fields wanted:
- Data classification: public / internal / personal / regulated
- Personal data involved: yes / no — if yes, list the fields and lawful basis

## 3. Network policy

- Max requests per minute:
- Max concurrent sessions:
- Retry policy:
- Proxy / egress requirements:
- Maintenance window:
- `robots.txt` reviewed: yes / no
- Terms of service reviewed: yes / no

## 4. Stop conditions

- [ ] The target asks for a CAPTCHA or human verification.
- [ ] The target returns repeated 401/403 after a reasonable retry.
- [ ] The target is outside the stated authorization.
- [ ] The data includes personal or regulated information without a lawful basis.
- [ ] The request rate would affect other users.
- [ ] The target owner asks us to stop.

## 5. Notes

{target.notes or "No extra notes."}
"""


def site_pack_readme(domain: str, source_case: str, lane: str | None, delivery: str | None) -> str:
    return f"""# Site pack — {domain}

This pack was promoted from case `{source_case}`.

- Lane: `{lane or "unrouted"}`
- Delivery: `{delivery or "unknown"}`
- Created: see `site.json`

## What belongs here

- `site.json` — machine-readable entrypoints, selectors, field map and policy.
- `spider/` — the Scrapling spider or a link to the generic spider.
- `repro/` — signature/replay code that reproduces the captured requests.
- `fixtures/` — small, non-secret request/response samples used by regression tests.
- `probe.json` / `route.json` — the original routing evidence.

## Rules

1. Never store cookies, tokens, API keys, or personal data in this pack.
2. Fixtures must be redacted and small enough to review.
3. Every selector change needs a fixture that proves the old and new behavior.
4. Run the regression test before using the pack on a live target.
"""


def case_next_steps() -> str:
    return """1. Read `scope.md` and confirm authorization.
2. Run `light-crawl probe <case>`.
3. Run `light-crawl route <case>` and follow the selected lane.
4. Capture evidence before writing code.
5. Reproduce the request outside the browser.
6. Build the spider.
7. Verify against fixtures and a 3-item live sample.
8. Record the gate with `light-crawl advance <case> VERIFIED --note "..."`.
9. Promote the reusable parts with `light-crawl learn <case>`.
"""
